using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class EchoTools
{
    [McpServerTool, Description("Echoes the input message back to the caller.")]
    public static string Echo(
        [Description("The message to echo")] string message)
    {
        return $"Echo: {message}";
    }

    [McpServerTool, Description("Returns the current server UTC time.")]
    public static string GetServerTime()
    {
        return DateTime.UtcNow.ToString("o");
    }
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(
        UriTemplate = "config://app/settings",
        Name = "App Settings",
        MimeType = "application/json"),
     Description("Returns application configuration data.")]
    public static string GetAppSettings()
    {
        var config = new
        {
            AppName = "HttpMcpServer",
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            MaxRetries = 3,
            TimeoutSeconds = 30
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(
        UriTemplate = "config://app/features",
        Name = "Feature Flags",
        MimeType = "application/json"),
     Description("Returns current feature flag settings.")]
    public static string GetFeatureFlags()
    {
        var flags = new
        {
            EnableCaching = true,
            EnableRateLimiting = false,
            EnableDetailedLogging = true
        };

        return JsonSerializer.Serialize(flags, new JsonSerializerOptions { WriteIndented = true });
    }
}

